<?php\n\nnamespace App\\Services;\n\nuse App\\Models\\ShopOrder;\nuse Illuminate\\Support\\Facades\\Http;\nuse Illuminate\\Support\\Facades\\Log;\n\nclass YandexPayService\n{\n    protected array $settings;\n    protected string $merchantId;\n    protected string $secretKey;\n    protected string $baseUrl;\n\n    public function __construct(array $settings)\n    {\n        $this->settings = $settings;\n        $mode = $this->settings['mode'] ?? 'test';\n        $this->merchantId = $this->settings['merchant_id'] ?? '';\n        $this->secretKey = $this->settings[\"secret_key_{\$mode}\"] ?? ($this->settings['secret_key'] ?? '');\n        $this->baseUrl = $mode === 'live' ? 'https://pay.yandex.ru/api/merchant/v1/' : 'https://sandbox.pay.yandex.ru/api/merchant/v1/';\n    }\n\n    public function initiatePayment(ShopOrder $order, float $amount, string $type = 'yandex_pay'): array\n    {\n        $returnUrl = config('app.frontend_url') . '/checkout?payment=return&order_id=' . $order->id;\n        $amountValue = number_format($amount, 2, '.', '');\n\n        $cartItems = [];\n        foreach ($order->items as $item) {\n            $cartItems[] = [\n                'productId' => $item->id,\n                'description' => $item->name,\n                'quantity' => ['count' => (string)$item->pivot->quantity],\n                'amount' => number_format($item->pivot->price, 2, '.', ''),\n                'total' => number_format($item->pivot->price * $item->pivot->quantity, 2, '.', ''),\n            ];\n        }\n\n        if ($order->delivery_cost > 0) {\n            $cartItems[] = [\n                'productId' => 'delivery',\n                'description' => 'Доставка',\n                'quantity' => ['count' => '1'],\n                'amount' => number_format($order->delivery_cost, 2, '.', ''),\n                'total' => number_format($order->delivery_cost, 2, '.', ''),\n            ];\n        }\n\n        $payload = [\n            'orderId' => $order->order_number . '-' . time(), // Ensure unique orderId for each attempt\n            'currencyCode' => 'RUB',\n            'amount' => $amountValue,\n            'description' => 'Оплата заказа №' . $order->order_number,\n            'cart' => [\n                'items' => $cartItems,\n                'total' => ['amount' => $amountValue],\n            ],\n            'redirectUrls' => [\n                'onSuccess' => $returnUrl . '&status=success',\n                'onError' => $returnUrl . '&status=error',\n            ],\n            'paymentMethodTypes' => ['CARD'],\n        ];\n\n        if ($type === 'yandex_split') {\n            $payload['paymentMethodTypes'] = ['SPLIT'];\n        }\n\n        try {\n            $response = Http::timeout(30)\n                ->retry(2, 1000)\n                ->withHeaders([\n                    'Authorization' => 'Api-Key ' . $this->secretKey,\n                    'X-Merchant-Id' => $this->merchantId,\n                    'Content-Type' => 'application/json',\n                    'Idempotence-Key' => uniqid('yp_', true),\n                ])\n                ->post($this->baseUrl . 'orders', $payload);\n\n            $data = $response->json();\n\n            if ($response->successful() && isset($data['paymentUrl'])) {\n                return [\n                    'success' => true,\n                    'payment_url' => $data['paymentUrl'],\n                    'transaction_id' => $data['orderId'],\n                    'request_data' => $payload,\n                    'response_data' => $data,\n                ];\n            } else {\n                Log::error('Yandex Pay API error', ['response' => $data, 'request' => $payload]);\n                return [\n                    'success' => false,\n                    'message' => $data['message'] ?? 'Yandex Pay API error',\n                    'request_data' => $payload,\n                    'response_data' => $data,\n                ];\n            }\n        } catch (\\Exception $e) {\n            Log::error('Yandex Pay request exception', ['error' => $e->getMessage()]);\n            return ['success' => false, 'message' => $e->getMessage()];\n        }\n    }\n}\n